var buttons1=document.getElementById("read-more");function readMore(){var e=document.getElementById("more");e.classList.toggle("show");var t=e.classList.contains("show")?"Mostra meno -":"Mostra di più +";buttons1.innerHTML=t,dots1()}function dots1(){document.getElementById("dots").classList.toggle("hidden-dots")}function dots(){for(var e=document.getElementsByClassName("dots"),t=0;t<e.length;t++)e[t].classList.toggle("hidden-dots")}function changeClass(){for(var e=document.getElementsByClassName("more"),t=document.querySelectorAll("button.read-more"),s=0;s<e.length;s++){e[s].classList.toggle("show");var n=e[s].classList.contains("show")?"Mostra meno -":"Mostra di più +";t.forEach((function(e){e.innerHTML=n}))}dots()}if(buttons1){buttons1.addEventListener("click",readMore);}document.querySelectorAll("button.read-more").forEach((function(e){e.addEventListener("click",changeClass)}));
